const std = @import("std"); const safe = @import("nt-safe-guar.zig"); const urln = @import("ut-urlz-norm.zig"); const flate = std.compress.flate; const http = std.http;
const CF = .{ .redb = 4096, .trnb = 8192, .okty = @as([]const []const u8, &.{ "text/", "application/json", "application/xml", "application/xhtml", "application/ld+json", "application/rss", "application/atom", "application/javascript" }), .oksf = @as([]const []const u8, &.{ "+json", "+xml" }) };
pub const Opts = struct { time_mill: u32 = 30000, body_maxz: usize = 5242880, redi_maxz: u8 = 5, uagt: []const u8 = "scra/0.1.0", priv_allo: bool = false, pdfz_maxz: usize = 0 };
pub const Cond = struct { etag: []const u8 = "", lmod: []const u8 = "" };
pub const Resp = struct { code: u16, body: []u8, ctyp: []u8, etag: []u8, lmod: []u8, finl: []u8, retr: u32,
pub fn free(self: *Resp, allo: std.mem.Allocator) void { allo.free(self.body); allo.free(self.ctyp); allo.free(self.etag); allo.free(self.lmod); allo.free(self.finl); self.* = undefined; } };
fn typeOkay(ctyp: []const u8, pdfz: bool) bool { if (ctyp.len == 0) return true; if (pdfz and std.ascii.startsWithIgnoreCase(ctyp, "application/pdf")) return true; var lowz: [96]u8 = undefined; const lenz = @min(ctyp.len, lowz.len); const head = std.ascii.lowerString(&lowz, ctyp[0..lenz]); for (CF.okty) |pref| if (std.mem.startsWith(u8, head, pref)) return true; const semi = std.mem.findScalar(u8, head, ';') orelse head.len; for (CF.oksf) |suff| if (std.mem.endsWith(u8, head[0..semi], suff)) return true; return false; }
fn locaJoin(allo: std.mem.Allocator, curz: []const u8, loca: []const u8) ![]u8 { const part = try urln.urlzSpli(curz); const por2 = if (part.dflt) try allo.dupe(u8, "") else try std.fmt.allocPrint(allo, ":{d}", .{part.port}); defer allo.free(por2); const base = try std.fmt.allocPrint(allo, "{s}://{s}{s}", .{ part.sche, part.host, por2 }); defer allo.free(base); if (std.mem.startsWith(u8, loca, "http://") or std.mem.startsWith(u8, loca, "https://")) return allo.dupe(u8, loca); if (std.mem.startsWith(u8, loca, "//")) return std.fmt.allocPrint(allo, "{s}:{s}", .{ part.sche, loca }); if (std.mem.startsWith(u8, loca, "/")) return std.fmt.allocPrint(allo, "{s}{s}", .{ base, loca }); const dirz = if (std.mem.findScalarLast(u8, part.path, '/')) |ind3| part.path[0 .. ind3 + 1] else "/"; return std.fmt.allocPrint(allo, "{s}{s}{s}", .{ base, dirz, loca }); }
fn tlszErrz(erro: anyerror) bool { const name = @errorName(erro); return std.mem.startsWith(u8, name, "Tls") or std.mem.startsWith(u8, name, "Certificate") or std.mem.eql(u8, name, "CertificateBundleLoadFailure"); }
fn hdrzOwnz(allo: std.mem.Allocator, head: http.Client.Response.Head, name: []const u8) ![]u8 { var iter = head.iterateHeaders(); while (iter.next()) |item| { if (std.ascii.eqlIgnoreCase(item.name, name)) return allo.dupe(u8, item.value); } return allo.dupe(u8, ""); }
pub fn fetcGetz(allo: std.mem.Allocator, iozz: std.Io, urlz: []const u8, opts: Opts, cond: Cond) !Resp { var hops: safe.Hops = .{ .maxz = @as(usize, opts.redi_maxz) + 1 }; var curz = try allo.dupe(u8, std.mem.trim(u8, urlz, " \t\r\n")); defer allo.free(curz); var clnt: http.Client = .{ .allocator = allo, .io = iozz }; defer clnt.deinit(); var hind: usize = 0; while (true) : (hind += 1) { const part = try urln.urlzSpli(curz); const norm = try urln.urlzNorm(allo, curz); defer allo.free(norm); try hops.visi(norm); try safe.hostChek(iozz, part.host, opts.priv_allo); const uric = std.Uri.parse(curz) catch return error.BadUrl; var heds: [2]http.Header = undefined; var hlen: usize = 0; if (hind == 0 and cond.etag.len > 0) { heds[hlen] = .{ .name = "If-None-Match", .value = cond.etag }; hlen += 1; } if (hind == 0 and cond.lmod.len > 0) { heds[hlen] = .{ .name = "If-Modified-Since", .value = cond.lmod }; hlen += 1; } var req2 = clnt.request(.GET, uric, .{ .redirect_behavior = .unhandled, .keep_alive = false, .headers = .{ .user_agent = .{ .override = opts.uagt } }, .extra_headers = heds[0..hlen] }) catch |err3| { if (tlszErrz(err3)) return error.NeedVendor; return err3; }; defer req2.deinit(); req2.accept_encoding = @splat(false); req2.accept_encoding[@backingInt(http.ContentEncoding.gzip)] = true; req2.accept_encoding[@backingInt(http.ContentEncoding.identity)] = true; req2.sendBodiless() catch |err3| { if (tlszErrz(err3)) return error.NeedVendor; return err3; }; var redb: [CF.redb]u8 = undefined; var resp = req2.receiveHead(&redb) catch |err3| { if (tlszErrz(err3)) return error.NeedVendor; return err3; }; const code: u16 = @backingInt(resp.head.status); const nobd = code == 204 or code == 304 or code < 200 or (code >= 300 and code < 400); if (nobd) { req2.response_content_length = 0; req2.response_transfer_encoding = .none; }
if (code >= 300 and code < 400 and code != 304) { const loca = resp.head.location orelse return error.BadRedirect; const nex2 = try locaJoin(allo, curz, loca); allo.free(curz); curz = nex2; continue; }
const ctyp = try hdrzOwnz(allo, resp.head, "content-type"); errdefer allo.free(ctyp); const etag = try hdrzOwnz(allo, resp.head, "etag"); errdefer allo.free(etag); const lmod = try hdrzOwnz(allo, resp.head, "last-modified"); errdefer allo.free(lmod); const retx = try hdrzOwnz(allo, resp.head, "retry-after"); defer allo.free(retx); const retr = std.fmt.parseInt(u32, retx, 10) catch 0; const lenz = resp.head.content_length; const encz = resp.head.content_encoding; const tenc = resp.head.transfer_encoding;
const ispd = std.ascii.startsWithIgnoreCase(ctyp, "application/pdf") and opts.pdfz_maxz > 0; const limz = if (ispd) opts.pdfz_maxz else opts.body_maxz; if (!nobd and !typeOkay(ctyp, opts.pdfz_maxz > 0)) return error.NotText;
if (!nobd and lenz != null and lenz.? > limz and encz == .identity) return error.TooBig;
var body: []u8 = undefined; if (nobd or req2.method == .HEAD) { body = try allo.dupe(u8, ""); } else { const trnb = try allo.alloc(u8, CF.trnb); defer allo.free(trnb); const winb = try allo.alloc(u8, flate.max_window_len); defer allo.free(winb); var deco: http.Decompress = undefined; _ = tenc; const rdrz = resp.readerDecompressing(trnb, &deco, winb); body = rdrz.allocRemaining(allo, .limited(limz)) catch |err3| switch (err3) { error.StreamTooLong => return error.TooBig, error.OutOfMemory => return error.OutOfMemory, error.ReadFailed => return resp.bodyErr() orelse error.ReadFailed }; }
errdefer allo.free(body); const finl = try allo.dupe(u8, curz); return .{ .code = code, .body = body, .ctyp = ctyp, .etag = etag, .lmod = lmod, .finl = finl, .retr = retr }; } }
